+/** Read-only frame access shared by flat replays and a candidate's two spans. */
+export interface FrameSequence<T> {
+  readonly length: number;
+  at(index: number): T | undefined;
+  slice(start?: number, end?: number): readonly T[];
+}
+
+/** A shared physical prefix plus an owned candidate suffix. Never flattens the
+ * full trajectory; consumers materialize only windows crossing the boundary. */
+export class FrameSpans<T> implements FrameSequence<T> {
+  readonly length: number;
+  constructor(private readonly prefix: readonly T[], private readonly suffix: readonly T[]) {
+    this.length = prefix.length + suffix.length;
+  }
+  at(index: number): T | undefined {
+    index = Math.trunc(index) || 0;
+    if (index < 0) index += this.length;
+    return index < this.prefix.length ? this.prefix[index] : this.suffix[index - this.prefix.length];
+  }
+  slice(start = 0, end = this.length): readonly T[] {
+    const normalize = (index: number) => {
+      index = Math.trunc(index) || 0;
+      return index < 0 ? Math.max(0, this.length + index) : Math.min(this.length, index);
+    };
+    const from = normalize(start), to = normalize(end), split = this.prefix.length;
+    if (to <= from) return [];
+    if (from >= split) return from === split && to === this.length ? this.suffix : this.suffix.slice(from - split, to - split);
+    if (to <= split) return from === 0 && to === split ? this.prefix : this.prefix.slice(from, to);
+    return this.prefix.slice(from).concat(this.suffix.slice(0, to - split));
+  }
+}
